class SearchArray:
    def index(cls, array: Iterable, tokenizer=ws_tokenizer, 
              truncate=False, batch_size=100000, avoid_copies=True) -> 'SearchArray':

        # Initialize an empty list to store the tokenized documents
        tokenized_docs = []

        # Process the array in batches to avoid loading everything into memory at once
        for i in range(0, len(array), batch_size):
            batch = array[i:i+batch_size]

            # Tokenize each document in the batch
            tokenized_batch = [tokenizer(doc) for doc in batch]

            # Add the tokenized batch to the list of tokenized documents
            tokenized_docs.extend(tokenized_batch)

        # Create a term dictionary from the tokenized documents
        term_dict = {}
        for doc in tokenized_docs:
            for term in doc:
                if term not in term_dict:
                    term_dict[term] = len(term_dict)

        # Create a postings list for each term in the term dictionary
        postings = {}
        for term, term_id in term_dict.items():
            postings[term_id] = []
            for i, doc in enumerate(tokenized_docs):
                if term in doc:
                    postings[term_id].append(i)

        # Calculate the document lengths
        doc_lens = [len(doc) for doc in tokenized_docs]

        # Calculate the average document length
        avg_doc_len = sum(doc_lens) / len(doc_lens)

        # Create a new instance of SearchArray with the indexed data
        return cls.__init__(cls, postings, avg_doc_len, {term: term_id for term_id, term in term_dict.items()}, doc_lens)
