def parse_min_should_match(num_clauses: int, spec: str) -> int:
    """
    This function parses the "min should match" specification (commonly referred to as 'mm' spec) 
    from Solr's search engine configuration and calculates the minimum number of clauses that must match 
    based on the given specification and the total number of clauses. It supports both absolute and 
    percentage-based specifications, as well as conditional specifications using '<'.

    Input-Output Arguments
    :param num_clauses: int, the total number of clauses in the query.
    :param spec: str, the 'min should match' specification as a string, which can include absolute numbers, 
                 percentages, and conditional expressions.
    :return: int, the calculated minimum number of clauses that must match according to the 'mm' spec.
    """

    # Check if the spec is an absolute number
    if spec.isdigit():
        # If it's an absolute number, return the number as the minimum number of clauses that must match
        return int(spec)

    # Check if the spec is a percentage
    elif spec.endswith('%'):
        # If it's a percentage, calculate the minimum number of clauses that must match
        percentage = float(spec.strip('%'))
        return int((percentage / 100) * num_clauses)

    # Check if the spec is a conditional expression using '<'
    elif '<' in spec:
        # If it's a conditional expression, split the spec into the condition and the value
        condition, value = spec.split('<')
        # Remove any leading or trailing whitespace from the condition and value
        condition = condition.strip()
        value = value.strip()

        # Check if the condition is an absolute number
        if condition.isdigit():
            # If the condition is an absolute number, check if the number of clauses is less than the condition
            if num_clauses < int(condition):
                # If the number of clauses is less than the condition, return the value as the minimum number of clauses that must match
                return parse_min_should_match(num_clauses, value)
            else:
                # If the number of clauses is not less than the condition, return the condition as the minimum number of clauses that must match
                return int(condition)

        # Check if the condition is a percentage
        elif condition.endswith('%'):
            # If the condition is a percentage, calculate the number of clauses that the condition represents
            condition_clauses = int((float(condition.strip('%')) / 100) * num_clauses)
            # Check if the number of clauses is less than the condition
            if num_clauses < condition_clauses:
                # If the number of clauses is less than the condition, return the value as the minimum number of clauses that must match
                return parse_min_should_match(num_clauses, value)
            else:
                # If the number of clauses is not less than the condition, return the condition as the minimum number of clauses that must match
                return int((float(condition.strip('%')) / 100) * num_clauses)

    # If the spec does not match any of the above conditions, raise a ValueError
    else:
        raise ValueError("Invalid 'mm' spec")
